FIELD_CATALOG['styling'] = list(dict.fromkeys(field for group in STYLE_FIELD_GROUPS.values() for field in group))
FIELD_CATALOG['backpack_row'] = FIELD_CATALOG['row']


def catalog_kinds() -> list[str]:
    return sorted(FIELD_CATALOG)


def suggest_fields(kind: str, text: str, *, limit: int = 5) -> list[str]:
    catalog_kind = {'backpack_row': 'row'}.get(kind, kind)
    choices = FIELD_CATALOG.get(catalog_kind, [])
    if not text or not choices:
        return []
    folded = {name.lower(): name for name in choices}
    matches = difflib.get_close_matches(text.lower(), list(folded), n=limit, cutoff=0.45)
    return [folded[name] for name in matches]


def fields_for(kind: str, *, contains: str | None = None, style_group: str | None = None) -> dict[str, Any]:
    if kind not in FIELD_CATALOG:
        raise ValueError(f'unknown field catalog kind: {kind}; expected one of {", ".join(catalog_kinds())}')
    if style_group is not None and kind != 'styling':
        raise ValueError('--style-group is only valid with kind=styling')
    if style_group is not None:
        if style_group not in STYLE_FIELD_GROUPS:
            raise ValueError(f'unknown style group: {style_group}; expected one of {", ".join(sorted(STYLE_FIELD_GROUPS))}')
        values = list(STYLE_FIELD_GROUPS[style_group])
    else:
        values = list(FIELD_CATALOG[kind])
    if contains:
        needle = contains.lower()
        values = [field for field in values if needle in field.lower()]
    out = {
        'kind': kind,
        'style_group': style_group,
        'contains': contains,
        'count': len(values),
        'fields': values,
        'source': {
            'icc_plus_version': ICC_PLUS_VERSION,
            'repository': SOURCE_REPOSITORY,
            'commit': SOURCE_COMMIT,
            'file': SOURCE_FILE,
        },
    }
    if contains and not values:
        candidates = STYLE_FIELD_GROUPS[style_group] if style_group else FIELD_CATALOG[kind]
        folded = {name.lower(): name for name in candidates}
        matches = difflib.get_close_matches(contains.lower(), list(folded), n=8, cutoff=0.35)
        out['suggestions'] = [folded[name] for name in matches]
    return out
